<h1>Config Health</h1><p>Files are the source of truth. Each load is validated; partial languages fall back per key.</p>
<section class="panel"><h2>ElevenLabs webhook</h2><p>Signing secret: <?= $webhookSecretConfigured ? 'Configured (value hidden)' : 'Not configured' ?>.</p><p>Endpoint: <code>webhook/elevenlabs.php</code></p>
<?php foreach ($webhookHealth->errors as $text): ?><p class="error"><?= $e($text) ?></p><?php endforeach ?>
<?php foreach ($webhookHealth->warnings as $text): ?><p class="notice webhook-warning"><?= $e($text) ?></p><?php endforeach ?>
<?php foreach ($agentMap as $agent => $shop): ?><p><code><?= $e($agent) ?></code> → <?= $e(is_string($shop) ? $shop : 'Invalid shop mapping') ?></p><?php endforeach ?>
<p>Map each real agent ID in config/env.php. Voice IDs below remain unusable until replaced in the shop JSON files.</p></section>
<?php foreach ($health as $id => $h): ?><section class="panel"><h2><?= $e($h['config']['shop_name'] ?? $id) ?></h2><code><?= $e($id) ?></code><?php if (!$h['errors']): ?><p class="success">Configuration valid</p><?php endif ?><?php foreach ($h['errors'] as $text): ?><p class="error"><?= $e($text) ?></p><?php endforeach ?><?php foreach ($h['warnings'] as $text): ?><p class="warning"><?= $e($text) ?></p><?php endforeach ?>
<?php foreach ($h['voices'] as $code => $v): ?><div class="panel"><h3><?= $e($code) ?> · enabled</h3><p><?= $e($v['provider']) ?> / <?= $e($v['gender']) ?></p><code><?= $e($v['voice_id']) ?></code><?php if ($v['fallback']): ?><p class="chip">placeholder or missing voice → fell back to <?= $e($v['language']) ?></p><?php endif ?><?php if ($v['placeholder']): ?><p>No usable voice configured yet; fallback is also a placeholder.</p><?php endif ?></div><?php endforeach ?>
<?php foreach ($h['fallbacks'] as $code => $f): ?><p><strong><?= $e($code) ?> closing:</strong> <?= $e($f['value']) ?> <?php if ($f['fallback']): ?><span class="chip">fallback · <?= $e($f['language']) ?></span><?php endif ?></p><?php endforeach ?></section><?php endforeach ?>
